import{_ as a,m as s,n,q as o}from"./chunks/framework.DMDh-7Lg.js";const u=JSON.parse('{"title":"Renderer","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/renderer.md","filePath":"concepts/renderer.md"}'),r={name:"concepts/renderer.md"};function t(l,e,i,c,p,d){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="renderer" tabindex="-1">Renderer <a class="header-anchor" href="#renderer" aria-label="Permalink to &quot;Renderer&quot;">​</a></h1><p>The renderer is the output abstraction in Klix. It gives the rest of the framework a small semantic surface for printing and screen clearing without exposing rich-specific details everywhere.</p><p>See also:</p><ul><li><a href="./ui">UI Namespace</a></li><li><a href="./../components/output">Output Components</a></li><li><a href="./../guides/theming">Theming</a></li></ul><h2 id="why-it-exists" tabindex="-1">Why It Exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to &quot;Why It Exists&quot;">​</a></h2><p>Not every terminal environment is a good match for full rich output. Klix uses a renderer layer so the rest of the framework can say:</p><ul><li>print this text</li><li>use this semantic color</li><li>clear the screen</li></ul><p>and let the renderer decide how to do that.</p><h2 id="renderer-types" tabindex="-1">Renderer Types <a class="header-anchor" href="#renderer-types" aria-label="Permalink to &quot;Renderer Types&quot;">​</a></h2><p>Current renderer classes:</p><ul><li><code>RichRenderer</code></li><li><code>FallbackRenderer</code></li><li><code>CIRenderer</code></li></ul><p>The selection happens in <code>klix.compat.get_renderer()</code>.</p><h2 id="richrenderer" tabindex="-1">RichRenderer <a class="header-anchor" href="#richrenderer" aria-label="Permalink to &quot;RichRenderer&quot;">​</a></h2><p>This is the normal interactive path. It:</p><ul><li>creates a <code>rich.console.Console</code></li><li>resolves semantic theme names like <code>accent</code> and <code>error</code></li><li>prints styled output through rich</li></ul><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Saved.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">success</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> bold</span><span style="color:#89DDFF;">=True)</span></span></code></pre></div><p>If rich is active, that becomes styled output through the console.</p><h2 id="fallbackrenderer" tabindex="-1">FallbackRenderer <a class="header-anchor" href="#fallbackrenderer" aria-label="Permalink to &quot;FallbackRenderer&quot;">​</a></h2><p>Fallback mode prints plain text and clears with escape sequences. It is intentionally minimal.</p><p>Use it as the baseline behavior when:</p><ul><li>colors are not reliable</li><li>the terminal is very limited</li><li>you care more about robustness than presentation</li></ul><h2 id="cirenderer" tabindex="-1">CIRenderer <a class="header-anchor" href="#cirenderer" aria-label="Permalink to &quot;CIRenderer&quot;">​</a></h2><p><code>CIRenderer</code> currently inherits from <code>FallbackRenderer</code>. It exists as a distinct mode because CI and pipes are a meaningful behavior boundary in the framework.</p><p>In practice, CI mode affects both:</p><ul><li>output rendering</li><li>input behavior</li></ul><p>See <a href="./input-engine">Input Engine</a>.</p><h2 id="color-resolution" tabindex="-1">Color Resolution <a class="header-anchor" href="#color-resolution" aria-label="Permalink to &quot;Color Resolution&quot;">​</a></h2><p>Renderers accept either:</p><ul><li>raw color values</li><li>semantic names from <code>ThemeConfig</code></li></ul><p>For example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Warning</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">warning</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>\n<span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Custom</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">#FFAA00</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="current-limitations" tabindex="-1">Current Limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current Limitations&quot;">​</a></h2><p>The renderer layer is intentionally narrow:</p><ul><li>it is not a full layout engine</li><li>it does not own complex stateful screen management</li><li>rich widgets are built above it in <code>session.ui.output</code></li></ul><p>That is a good thing. It keeps the boundary clean.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><h3 id="writing-component-code-against-rich-console-console-directly-everywhere" tabindex="-1">Writing component code against <code>rich.console.Console</code> directly everywhere <a class="header-anchor" href="#writing-component-code-against-rich-console-console-directly-everywhere" aria-label="Permalink to &quot;Writing component code against `rich.console.Console` directly everywhere&quot;">​</a></h3><p>If you skip the renderer surface entirely, your code becomes harder to run in fallback environments.</p><h3 id="treating-cirenderer-as-just-visual-fallback" tabindex="-1">Treating <code>CIRenderer</code> as just visual fallback <a class="header-anchor" href="#treating-cirenderer-as-just-visual-fallback" aria-label="Permalink to &quot;Treating `CIRenderer` as just visual fallback&quot;">​</a></h3><p>It is also a signal that input should become non-interactive.</p>',41)])])}const y=a(r,[["render",t]]);export{u as __pageData,y as default};
